import java.io.InputStream;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.io.IOException;
import java.util.Arrays;

public class Main {
    public static void main(String[] args) throws IOException {
        InputReader in = new InputReader(System.in);
        OutputWriter out = new OutputWriter(System.out);
        int n = in.nextInt();
        int m = in.nextInt();
        ModInt mod = new ModInt(m);
        int[] fact = new int[n + 1];
        fact[0] = n;
        for (int i = 1; i < n; i++) fact[i] = mod.mul(fact[i - 1], n - i);
        int size = n * (n - 1) + 1;
        int[] dp = new int[size];
        int mid = (n * (n - 1)) / 2;
        dp[mid] = 1;
        int ans = 0;
        for (int i = n - 1; i >= 0; i--) {
            int c = n - 1 - i;
            int[] tmp = dp.clone();
            Arrays.fill(dp, 0);
            int lim = (c * (c - 1)) / 2;
            int cnt = 0;
            for (int cur = -c; cur < 0; cur++) {
                int pairs = c + cur + 1;
                for (int j = mid - cur + 1; j <= mid + lim; j++)
                    cnt = mod.add(cnt, mod.mul(tmp[j], pairs));
            }
            ans = mod.add(ans, mod.mul(cnt, i == 0 ? 1 : fact[i - 1]));
            for (int j = mid - lim; j <= mid + lim; j++) {
                for (int cur = -c; cur <= c; cur++) {
                    int pairs = c - Math.abs(cur) + 1;
                    dp[j + cur] = mod.add(dp[j + cur], mod.mul(pairs, tmp[j]));
                }
            }
        }
        out.println(ans);
        out.close();
    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar, numChars;
        InputReader(InputStream s) { stream = s; }
        private int read() throws IOException {
            if (numChars == -1) throw new IOException();
            if (curChar >= numChars) {
                curChar = 0;
                numChars = stream.read(buf);
                if (numChars <= 0) return -1;
            }
            return buf[curChar++];
        }
        public int nextInt() throws IOException {
            int c = read();
            while (c <= 32) c = read();
            int sgn = 1;
            if (c == '-') { sgn = -1; c = read(); }
            int res = 0;
            while (c >= '0' && c <= '9') {
                res = res * 10 + (c - '0');
                c = read();
            }
            return res * sgn;
        }
    }

    static class OutputWriter {
        private PrintWriter pw;
        OutputWriter(OutputStream os) { pw = new PrintWriter(os, true); }
        public void println(Object o) { pw.println(o); }
        public void close() { pw.close(); }
    }

    static class ModInt {
        int mod;
        ModInt(int m) { mod = m; }
        int add(int a, int b) { a += b; if (a >= mod) a -= mod; return a; }
        int mul(int a, int b) { return (int)((a * 1L * b) % mod); }
    }
}
